function useTranslation(locale) {
  const dict = locale === 'pt-BR' ? ptBR : en;
  return (key) => dict[key] ?? key;
}

new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(1234.5);
// "R$ 1.234,50"

new Intl.DateTimeFormat('en-US').format(new Date());
// "1/15/2025"
